import{_ as a,o as r,c as o,a2 as s}from"./chunks/framework.CqGPl1zp.js";const t="/newx-doc/assets/%E7%95%8C%E9%9D%A2.2sFAhpME.png",n="/newx-doc/assets/%E8%A1%A8%E7%BB%93%E6%9E%84.DfhTgy-G.png",l="/newx-doc/assets/%E6%8E%A5%E6%94%B6%E6%99%AE%E9%80%9A%E6%B6%88%E6%81%AF.50Z5JytX.png",c="/newx-doc/assets/%E8%A2%AB%E5%8A%A8%E5%9B%9E%E5%A4%8D%E7%94%A8%E6%88%B7%E6%B6%88%E6%81%AF.yzL1yFEm.png",i="/newx-doc/assets/%E4%B8%BB%E5%8A%A8%E5%8F%91%E9%80%81%E6%B6%88%E6%81%AF%E7%BB%99%E7%94%A8%E6%88%B7.Bn_TxEFb.png",m="/newx-doc/assets/%E5%AE%A2%E6%9C%8D%E6%B6%88%E6%81%AF.DUNVSKXv.png",v=JSON.parse('{"title":"公众号消息","description":"","frontmatter":{},"headers":[],"relativePath":"mp/message.md","filePath":"mp/message.md","lastUpdated":null}'),p={name:"mp/message.md"};function d(u,e,_,h,g,f){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="公众号消息" tabindex="-1">公众号消息 <a class="header-anchor" href="#公众号消息" aria-label="Permalink to &quot;公众号消息&quot;">​</a></h1><p>本章节，讲解公众号消息的相关内容，对应 [公众号管理 -&gt; 消息管理] 菜单。如下图所示：</p><p><img src="'+t+'" alt="消息管理"></p><h2 id="_1-表结构" tabindex="-1">1. 表结构 <a class="header-anchor" href="#_1-表结构" aria-label="Permalink to &quot;1. 表结构&quot;">​</a></h2><p>公众号消息对应 <code>mp_message</code> 表，结构如下图所示：</p><p><img src="'+n+'" alt="表结构"></p><p>① <code>type</code> 字段：消息类型，包括文本、图片、语音、视频、小视频、图文、音乐、地理位置、链接、事件等类型，对应 <code>mp_message_type</code> 字典。</p><p>② <code>send_from</code> 字段：消息发送方，分成两类：</p><ul><li>【接收】用户发送给公众号：<a href="https://developers.weixin.qq.com/doc/offiaccount/Message_Management/Receiving_standard_messages.html" target="_blank" rel="noreferrer">接收普通消息</a> 、<a href="https://developers.weixin.qq.com/doc/offiaccount/Message_Management/Receiving_event_pushes.html" target="_blank" rel="noreferrer">接收事件推送</a></li><li>【发送】公众号发给用户：<a href="https://developers.weixin.qq.com/doc/offiaccount/Message_Management/Passive_user_reply_message.html" target="_blank" rel="noreferrer">被动回复用户消息</a> 、<a href="https://developers.weixin.qq.com/doc/offiaccount/Message_Management/Service_Center_messages.html" target="_blank" rel="noreferrer">客服消息</a></li></ul><h2 id="_2-消息管理界面" tabindex="-1">2. 消息管理界面 <a class="header-anchor" href="#_2-消息管理界面" aria-label="Permalink to &quot;2. 消息管理界面&quot;">​</a></h2><ul><li>前端：<a href="https://github.com/yudaocode/yudao-ui-admin-vue2/blob/master/src/views/mp/message/index.vue" target="_blank" rel="noreferrer">/@views/mp/message</a></li><li>后端：<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/controller/admin/message/MpMessageController.java" target="_blank" rel="noreferrer">MpMessageController</a></li></ul><h2 id="_3-【接收】" tabindex="-1">3.【接收】 <a class="header-anchor" href="#_3-【接收】" aria-label="Permalink to &quot;3.【接收】&quot;">​</a></h2><h3 id="_3-1-接收普通消息" tabindex="-1">3.1 接收普通消息 <a class="header-anchor" href="#_3-1-接收普通消息" aria-label="Permalink to &quot;3.1 接收普通消息&quot;">​</a></h3><blockquote><p>对应 <a href="https://developers.weixin.qq.com/doc/offiaccount/Message_Management/Receiving_standard_messages.html" target="_blank" rel="noreferrer">《微信公众号官方文档 —— 接收普通消息》</a> 文档。</p></blockquote><p>当用户向公众账号发消息时，会被 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/handler/message/MessageReceiveHandler.java" target="_blank" rel="noreferrer">MessageReceiveHandler</a> 处理，记录到 <code>mp_message</code> 表，消息类型为文本、图片、语音、视频、小视频、地理位置、链接。如下图所示：</p><p><img src="'+l+'" alt="接收普通消息"></p><h3 id="_3-2-接收事件消息" tabindex="-1">3.2 接收事件消息 <a class="header-anchor" href="#_3-2-接收事件消息" aria-label="Permalink to &quot;3.2 接收事件消息&quot;">​</a></h3><blockquote><p>对应 <a href="https://developers.weixin.qq.com/doc/offiaccount/Message_Management/Receiving_event_pushes.html" target="_blank" rel="noreferrer">《微信公众号官方文档 —— 接收事件推送》</a> 文档。</p></blockquote><p>在用户和公众号产交互的过程中，会被 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/handler/message/MessageReceiveHandler.java" target="_blank" rel="noreferrer">MessageReceiveHandler</a> 处理，记录到 <code>mp_message</code> 表，消息类型仅为事件。</p><h2 id="_4-【发送】" tabindex="-1">4.【发送】 <a class="header-anchor" href="#_4-【发送】" aria-label="Permalink to &quot;4.【发送】&quot;">​</a></h2><h3 id="_4-1-被动回复用户消息" tabindex="-1">4.1 被动回复用户消息 <a class="header-anchor" href="#_4-1-被动回复用户消息" aria-label="Permalink to &quot;4.1 被动回复用户消息&quot;">​</a></h3><blockquote><p>对应 <a href="https://developers.weixin.qq.com/doc/offiaccount/Message_Management/Passive_user_reply_message.html" target="_blank" rel="noreferrer">《微信公众号官方文档 —— 被动回复用户消息》</a> 文档。</p></blockquote><p>在被动回复用户消息时，统一由 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/message/MpMessageServiceImpl.java#L85-L104" target="_blank" rel="noreferrer">MpMessageServiceImpl</a> 的 <code>sendOutMessage</code> 方法来构建回复消息，也会记录到 <code>mp_message</code> 表，消息类型为文本、图片、语音、视频、音乐、图文。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-mp-api 和 yudao-module-mp-biz 子模块，代码直接合并到 yudao-module-mp 模块的 src 目录下，更适合单体项目</p><p><img src="'+c+'" alt="被动回复用户消息"></p><h3 id="_4-2-主动发送客服消息" tabindex="-1">4.2 主动发送客服消息 <a class="header-anchor" href="#_4-2-主动发送客服消息" aria-label="Permalink to &quot;4.2 主动发送客服消息&quot;">​</a></h3><blockquote><p>对应 <a href="https://developers.weixin.qq.com/doc/offiaccount/Message_Management/Service_Center_messages.html" target="_blank" rel="noreferrer">《微信公众号官方文档 —— 客服消息》</a> 文档。</p></blockquote><p>点击消息管理界面的【消息】按钮，可以主动发送客服消息给用户。如下图所示：</p><p><img src="'+i+'" alt="主动发送消息给用户"></p><p>主动发送客服消息，统一由 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/message/MpMessageServiceImpl.java#L106-L130" target="_blank" rel="noreferrer">MpMessageServiceImpl</a> 的 <code>sendKefuMessage</code> 方法来构建客服消息，也会记录到 <code>mp_message</code> 表，消息类型为文本、图片、语音、视频、音乐、图文。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-mp-api 和 yudao-module-mp-biz 子模块，代码直接合并到 yudao-module-mp 模块的 src 目录下，更适合单体项目</p><p><img src="'+m+'" alt="客服消息"></p>',32)])])}const q=a(p,[["render",d]]);export{v as __pageData,q as default};
